#define _GNU_SOURCE

#include <errno.h>
#include <fcntl.h>
#include <linux/futex.h>
#include <linux/netlink.h>
#include <linux/vm_sockets.h>
#include <poll.h>
#include <signal.h>
#include <stdint.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/socket.h>
#include <sys/stat.h>
#include <sys/syscall.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

struct call_result {
    long rc;
    int error;
};

static struct call_result socket_result(int domain, int type, int protocol) {
    errno = 0;
    int fd = socket(domain, type, protocol);
    struct call_result result = { .rc = fd, .error = fd < 0 ? errno : 0 };
    if (fd >= 0) {
        close(fd);
        result.rc = 0;
    }
    return result;
}

struct compat_observation {
    struct call_result socket_result;
    int connected;
    int connect_error;
    int skipped;
    int child_exit;
    int child_signal;
    int timed_out;
};

static struct call_result compat_vsock_socket(int *connected, int *connect_error) {
    struct call_result result = { .rc = -1, .error = ENOSYS };
    *connected = 0;
    *connect_error = 0;
#if defined(__x86_64__) && defined(MAP_32BIT)
    void *page = mmap(NULL, 4096, PROT_READ | PROT_WRITE,
                      MAP_PRIVATE | MAP_ANONYMOUS | MAP_32BIT, -1, 0);
    if (page == MAP_FAILED) {
        result.error = errno;
        return result;
    }

    uint32_t *args = page;
    if ((uintptr_t)args > UINT32_MAX) {
        result.error = EOVERFLOW;
        munmap(page, 4096);
        return result;
    }
    args[0] = AF_VSOCK;
    args[1] = SOCK_STREAM | SOCK_CLOEXEC | SOCK_NONBLOCK;
    args[2] = 0;

    register long rax __asm__("rax") = 102; /* i386 __NR_socketcall */
    register long rbx __asm__("rbx") = 1;   /* SYS_SOCKET */
    register long rcx __asm__("rcx") = (uintptr_t)args;
    __asm__ volatile("int $0x80"
                     : "+a"(rax)
                     : "b"(rbx), "c"(rcx)
                     : "memory", "cc", "r8", "r9", "r10", "r11");

    int32_t compat_ret = (int32_t)(uint32_t)rax;
    if (compat_ret < 0 && compat_ret >= -4095) {
        result.error = -compat_ret;
        munmap(page, 4096);
        return result;
    }

    int fd = compat_ret;
    result.rc = 0;
    result.error = 0;

    struct sockaddr_vm host;
    memset(&host, 0, sizeof(host));
    host.svm_family = AF_VSOCK;
    host.svm_cid = VMADDR_CID_HOST;
    host.svm_port = 3000;
    errno = 0;
    if (connect(fd, (struct sockaddr *)&host, sizeof(host)) == 0) {
        *connected = 1;
    } else if (errno == EINPROGRESS) {
        struct pollfd descriptor = { .fd = fd, .events = POLLOUT };
        int poll_rc = poll(&descriptor, 1, 1000);
        if (poll_rc > 0) {
            int socket_error = 0;
            socklen_t socket_error_size = sizeof(socket_error);
            if (getsockopt(fd, SOL_SOCKET, SO_ERROR, &socket_error,
                           &socket_error_size) == 0 && socket_error == 0) {
                *connected = 1;
            } else {
                *connect_error = socket_error != 0 ? socket_error : errno;
            }
        } else {
            *connect_error = poll_rc == 0 ? ETIMEDOUT : errno;
        }
    } else {
        *connect_error = errno;
    }
    close(fd);
    munmap(page, 4096);
#endif
    return result;
}

static struct compat_observation observe_compat_vsock(void) {
    struct compat_observation observation = {
        .socket_result = { .rc = -1, .error = ENOSYS },
        .connected = 0,
        .connect_error = 0,
        .skipped = 0,
        .child_exit = -1,
        .child_signal = 0,
        .timed_out = 0,
    };
    if (getenv("SKIP_COMPAT_VSOCK") != NULL) {
        observation.socket_result.error = ENOTSUP;
        observation.skipped = 1;
        return observation;
    }

    int report_pipe[2] = { -1, -1 };
    if (pipe2(report_pipe, O_CLOEXEC | O_NONBLOCK) != 0) {
        observation.socket_result.error = errno;
        return observation;
    }

    pid_t child = fork();
    if (child < 0) {
        observation.socket_result.error = errno;
        close(report_pipe[0]);
        close(report_pipe[1]);
        return observation;
    }
    if (child == 0) {
        close(report_pipe[0]);
        struct compat_observation child_report = observation;
        child_report.socket_result = compat_vsock_socket(
            &child_report.connected, &child_report.connect_error);
        (void)write(report_pipe[1], &child_report, sizeof(child_report));
        close(report_pipe[1]);
        _exit(0);
    }

    close(report_pipe[1]);
    struct pollfd descriptor = { .fd = report_pipe[0], .events = POLLIN | POLLHUP };
    int poll_rc = poll(&descriptor, 1, 2000);
    if (poll_rc > 0) {
        ssize_t received = read(report_pipe[0], &observation, sizeof(observation));
        if (received != (ssize_t)sizeof(observation)) {
            observation.socket_result.rc = -1;
            observation.socket_result.error = EIO;
        }
    } else if (poll_rc == 0) {
        observation.timed_out = 1;
        observation.socket_result.rc = -1;
        observation.socket_result.error = ETIMEDOUT;
        (void)kill(child, SIGKILL);
    } else {
        observation.socket_result.rc = -1;
        observation.socket_result.error = errno;
    }
    close(report_pipe[0]);

    int status = 0;
    if (waitpid(child, &status, 0) == child) {
        if (WIFEXITED(status)) observation.child_exit = WEXITSTATUS(status);
        if (WIFSIGNALED(status)) observation.child_signal = WTERMSIG(status);
    }
    return observation;
}

static struct call_result futex_call(uint32_t *address, int operation,
                                     uint32_t value, const void *timeout,
                                     uint32_t *second_address, uint32_t third_value) {
    errno = 0;
    long rc = syscall(SYS_futex, address, operation, value, timeout,
                      second_address, third_value);
    struct call_result result = { .rc = rc, .error = rc < 0 ? errno : 0 };
    return result;
}

int main(void) {
    struct call_result ipv6 = socket_result(AF_INET6, SOCK_DGRAM | SOCK_CLOEXEC, 0);
    struct call_result netlink = socket_result(AF_NETLINK, SOCK_RAW | SOCK_CLOEXEC, NETLINK_ROUTE);
    struct call_result unix_socket = socket_result(AF_UNIX, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct call_result algorithm_socket = socket_result(AF_ALG, SOCK_SEQPACKET | SOCK_CLOEXEC, 0);
    struct call_result direct_vsock = socket_result(AF_VSOCK, SOCK_STREAM | SOCK_CLOEXEC, 0);
    struct compat_observation compat_vsock = observe_compat_vsock();

    uint32_t pi_word = 0;
    struct call_result futex_lock = futex_call(&pi_word,
        FUTEX_LOCK_PI | FUTEX_PRIVATE_FLAG, 0, NULL, NULL, 0);
    struct call_result futex_unlock = { .rc = -999, .error = 0 };
    if (futex_lock.rc == 0) {
        futex_unlock = futex_call(&pi_word,
            FUTEX_UNLOCK_PI | FUTEX_PRIVATE_FLAG, 0, NULL, NULL, 0);
    }
    uint32_t requeue_word = 0;
    struct call_result futex_requeue_pi = futex_call(&requeue_word,
        FUTEX_CMP_REQUEUE_PI | FUTEX_PRIVATE_FLAG, 0, NULL,
        &requeue_word, 0);

    int sock = socket(AF_INET6, SOCK_DGRAM | SOCK_CLOEXEC, 0);
    int pipefd[2] = { -1, -1 };
    int pipe_rc = pipe2(pipefd, O_CLOEXEC | O_NONBLOCK);

    struct call_result splice_result = { .rc = -999, .error = 0 };
    if (sock >= 0 && pipe_rc == 0) {
        errno = 0;
        splice_result.rc = splice(pipefd[0], NULL, sock, NULL, 0, SPLICE_F_NONBLOCK);
        splice_result.error = splice_result.rc < 0 ? errno : 0;
    }

    struct call_result sendmsg_result = { .rc = -999, .error = 0 };
    if (sock >= 0) {
        struct msghdr message;
        memset(&message, 0, sizeof(message));
        errno = 0;
        sendmsg_result.rc = sendmsg(sock, &message, MSG_DONTWAIT);
        sendmsg_result.error = sendmsg_result.rc < 0 ? errno : 0;
    }

    if (pipefd[0] >= 0) close(pipefd[0]);
    if (pipefd[1] >= 0) close(pipefd[1]);
    if (sock >= 0) close(sock);

    printf("{\"uid\":%ld,\"gid\":%ld,"
           "\"proc_if_inet6_readable\":%s,"
           "\"socket_af_inet6_udp\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_netlink_route\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_unix_stream\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_alg_seqpacket\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_vsock_direct\":{\"rc\":%ld,\"errno\":%d},"
           "\"socket_af_vsock_i386_socketcall\":{\"skipped\":%s,"
           "\"rc\":%ld,\"errno\":%d,\"cid2_port3000_connected\":%s,"
           "\"connect_errno\":%d,\"child_exit\":%d,\"child_signal\":%d,"
           "\"timed_out\":%s},"
           "\"futex_lock_pi_private\":{\"rc\":%ld,\"errno\":%d},"
           "\"futex_unlock_pi_private\":{\"rc\":%ld,\"errno\":%d},"
           "\"futex_cmp_requeue_pi_same_address\":{\"rc\":%ld,\"errno\":%d},"
           "\"splice_zero_length\":{\"rc\":%ld,\"errno\":%d},"
           "\"sendmsg_empty_no_more\":{\"rc\":%ld,\"errno\":%d}}\n",
           (long)getuid(), (long)getgid(),
           access("/proc/net/if_inet6", R_OK) == 0 ? "true" : "false",
           ipv6.rc, ipv6.error,
           netlink.rc, netlink.error,
           unix_socket.rc, unix_socket.error,
           algorithm_socket.rc, algorithm_socket.error,
           direct_vsock.rc, direct_vsock.error,
           compat_vsock.skipped ? "true" : "false",
           compat_vsock.socket_result.rc, compat_vsock.socket_result.error,
           compat_vsock.connected ? "true" : "false", compat_vsock.connect_error,
           compat_vsock.child_exit, compat_vsock.child_signal,
           compat_vsock.timed_out ? "true" : "false",
           futex_lock.rc, futex_lock.error,
           futex_unlock.rc, futex_unlock.error,
           futex_requeue_pi.rc, futex_requeue_pi.error,
           splice_result.rc, splice_result.error,
           sendmsg_result.rc, sendmsg_result.error);
    return 0;
}
